#include <iostream>
using namespace std;
int main()
{
int t;
cin>>t;
while(t--)
{
    int n,m,in=0;
    cin>>n>>m;
    for(int i=0;i<n;++i)
    {
    int a,b;
    cin>>a>>b;
    if(a%2!=(b+in)%2){--m;in=in^1;}
    }
    cout<<m<<endl;
}
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
int t,n,m,x[200005],y[200005];
int main() {
	cin>>t;
	while(t--)
	{
		cin>>n>>m;
		for(int i=1;i<=n;i++)
			cin>>x[i]>>y[i];
		for(int i=1;i<=n;i++)
			if((x[i]-x[i-1])%2!=abs(y[i]-y[i-1]))
				m--;
		cout<<m<<"\n";
	}
	return 0;
}

